p=argparse.ArgumentParser();p.add_argument('--private',type=Path,required=True);p.add_argument('--windows',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();arc=np.load(a.private/'canonical_trace.npz');z={k:arc[k] for k in arc.files};arc.close();f=np.load(a.private/'feedback_series.npz');c=np.load(a.private/'canonical_checkpoints.npz');idx=np.flatnonzero(z['stage']==2);pre=z['before'][idx];post=z['after'][idx];R=pre[:,6:15].reshape(-1,3,3);Rp=post[:,6:15].reshape(-1,3,3);RN=R@Rotation.from_rotvec(z['innovation'][idx,3:]).as_matrix();yaw=lambda M:Rotation.from_matrix(M).as_euler('xyz')[:,2];wrap=lambda q:np.angle(np.exp(1j*q));yp=yaw(R);ya=yaw(Rp);yn=yaw(RN);error_pre=wrap(yp-yn);error_post=wrap(ya-yn);delta_yaw=wrap(ya-yp);new_yaw=np.r_[np.nan,wrap(np.diff(yp)-delta_yaw[:-1]-np.diff(yn))];seq=z['ingest_index'][idx];omega=c['imu_omega0'][seq];vb=np.einsum('nji,nj->ni',R,pre[:,3:6])-np.cross(omega-pre[:,15:18],np.load(a.private/'initial.npz')['lever']);whole_dt=np.diff(z['header'][idx])*1e-9;rows=[];wind=json.loads(a.windows.read_text());guard={}
