 for label,i in [('padding_begin',int(np.flatnonzero(f['header']>=lo)[0])),('entry',int(ii[0])),('exit',int(ii[-1]))]:
  by.append(dict(location=label,frame=i,GNSS_prior_difference=float(f['GNSS_balance_prior_difference'][i]) if f['valid'][i] else None,GNSS_posterior_difference=float(f['GNSS_balance_posterior_difference'][i]) if f['valid'][i] else None,prior_minus_NDT_yaw_deg=float(np.rad2deg(error_pre[i])),posterior_minus_NDT_yaw_deg=float(np.rad2deg(error_post[i]))))
